def make_visual(title, primitive_type, primitive_id, pos_y_top, pos_y_bot, caption, is_vert, **kwargs):
    """Helper to build 3b1b-style visual data with dark mode colors."""
    return json.dumps([
        {"type": "text", "id": "title", "text": title, "pos": [0.0, pos_y_top, 0], "color": "#F2F3F5", "font_size": 28 if is_vert else 32},
        {"type": primitive_type, "id": primitive_id, **kwargs},
        {"type": "text", "id": "caption", "text": caption, "pos": [0.0, pos_y_bot, 0], "color": "#F1C40F", "font_size": 21 if is_vert else 24}
    ])

def make_beats(is_vert=False):
    if is_vert:
        return json.dumps([
            {"type": "hook", "focus": "model"}, {"type": "promise", "focus": "model", "transition": "push"},
            {"type": "experiment", "focus": "model", "transition": "wipe"}, {"type": "law", "focus": "model", "transition": "zoom_blur"},
            {"type": "emphasis", "focus": "model", "transition": "push"}, {"type": "punchline", "focus": "model", "transition": "wipe"}
        ])
    else:
        return json.dumps([
            {"type": "hook", "focus": "model"}, {"type": "promise", "focus": "model", "transition": "push"},
            {"type": "experiment", "focus": "model", "transition": "wipe"}, {"type": "law", "focus": "model", "transition": "zoom_blur"},
            {"type": "midpoint", "focus": "model", "transition": "push"}, {"type": "experiment", "focus": "model", "transition": "wipe"},
            {"type": "emphasis", "focus": "model", "transition": "zoom_blur"}, {"type": "punchline", "focus": "model", "transition": "push"},
            {"type": "cta", "focus": "model", "transition": "wipe"}
        ])

