videos.append({"video_id": "hz_v1_principle_least_action", "concept_type": "MECHANICS", "header_title": "The Principle of Least Action", "tagline": "Nature's ultimate shortcut", "question_text": "How does a thrown ball know its trajectory in advance?", "option_a": "It feels the gravitational pull.", "option_b": "It minimizes the Action (T - V) over time.", "option_c": "It follows a parabolic guess.", "option_d": "It conserves momentum.", "correct_answer": "B", "equations_json": json.dumps(["S = \\int_{t_1}^{t_2} (T - V) dt", "\\delta S = 0"]), "visual_data_json": make_visual("The Principle of Least Action", "calculus_graph", "model", 4.5, -4.5, "integral_area: the path of minimum action", False, function="action_functional", color="#4CC9F0"), "audio_script": "When you throw a ball, it traces a perfect parabola. But how does the ball 'know' which path to take before it gets there? It doesn't. Nature has a deeper rule. Imagine calculating a number called the Action for every possible path the ball could take. The Action is the difference between kinetic and potential energy, integrated over time. The actual path the ball takes is the one where this number is at an absolute minimum. If you nudge the path even slightly, the Action doesn't change. It’s not magic; it’s a mathematical consequence of quantum mechanics, where all possible paths interfere with each other, and only the minimum Action path survives. We call it the Principle of Least Action, and it is the single most profound bookkeeping rule in the universe.", "orientation": "horizontal", "beats_json": make_beats(False), "target_duration_sec": 180})
videos.append({"video_id": "hz_v3_double_slit", "concept_type": "QUANTUM", "header_title": "The Only Mystery", "tagline": "When arrows add up to zero", "question_text": "What causes the dark bands in the double-slit experiment?", "option_a": "Particles collide and bounce back.", "option_b": "Probability amplitudes cancel out.", "option_c": "The screen absorbs specific energies.", "option_d": "Light bends around the slits.", "correct_answer": "B", "equations_json": json.dumps(["P = |\\psi_A + \\psi_B|^2", "\\psi = e^{i(kx - \\omega t)}"]), "visual_data_json": make_visual("The Double-Slit Experiment", "two_path_interference", "model", 5.0, -5.0, "phasor arrows adding tip-to-tail", False, slits=2, color="#7209B7"), "audio_script": "Richard Feynman called the double-slit experiment the 'only mystery' of quantum mechanics. Why? Because an electron doesn't just go through slit A or slit B. It behaves like a wave of probability. We represent this with a complex arrow, or phasor, that rotates as time passes. When we add the arrow from slit A to the arrow from slit B tip-to-tail, we get a new arrow. The probability of finding the electron is the square of the length of this final arrow. Where the arrows point in opposite directions and cancel out, the probability is zero, and you get a dark band on the screen. It is completely absurd, yet it is exactly how nature works.", "orientation": "horizontal", "beats_json": make_beats(False), "target_duration_sec": 180})
videos.append({"video_id": "hz_v2_magnetism_relativity", "concept_type": "ELECTROMAGNETISM", "header_title": "Magnetism is Relativity", "tagline": "Length contraction makes the B-field", "question_text": "Why does a moving charge feel a magnetic force?", "option_a": "Moving charges generate heat.", "option_b": "Length contraction makes the wire charged in the moving frame.", "option_c": "Friction with the vacuum.", "option_d": "The electron spins faster.", "correct_answer": "B", "equations_json": json.dumps(["L = L_0 \\sqrt{1 - v^2/c^2}", "\\vec{F}_B = q \\vec{v} \\times \\vec{B}"]), "visual_data_json": make_visual("Magnetism & Relativity", "vector_field", "model", 5.0, -5.0, "proton lattice contracting", False, field_type="coulomb_contracting", color="#3A86FF"), "audio_script": "Why does a moving charge feel a magnetic force, but a stationary one doesn't? Magnetism isn't a separate force; it is just electricity viewed from a different reference frame. Imagine a wire with positive protons and negative electrons. If you move alongside the electrons, special relativity says the space between the stationary protons contracts. The wire is now positively charged in your frame! The repulsive electric force you feel is what we call the magnetic force. Relativity demands that magnetism exists, or electricity would violate the laws of physics for moving observers.", "orientation": "horizontal", "beats_json": make_beats(False), "target_duration_sec": 180})
videos.append({"video_id": "hz_v1_hamiltonian_phase", "concept_type": "MECHANICS", "header_title": "Phase Space Flows", "tagline": "The geometry of motion", "question_text": "What does Liouville's Theorem say about phase space?", "option_a": "Volume is conserved as systems evolve.", "option_b": "Energy is always lost to heat.", "option_c": "Particles stop moving at equilibrium.", "option_d": "Orbits always decay.", "correct_answer": "A", "equations_json": json.dumps(["\\frac{dp}{dt} = -\\frac{\\partial H}{\\partial q}", "\\frac{dq}{dt} = \\frac{\\partial H}{\\partial p}"]), "visual_data_json": make_visual("Hamiltonian Mechanics", "calculus_graph", "model", 5.0, -5.0, "contours of constant energy", False, function="hamiltonian_flow", color="#FB5607"), "audio_script": "Newton gave us forces and accelerations. But Hamilton gave us geometry. Instead of tracking where a particle is and how fast it is going, we plot its position and momentum on a single map called phase space. The motion of the system is just a flow along the contour lines of a single function: the Hamiltonian. The most beautiful part? Liouville's theorem. If you draw a box around a group of states in this space, the box might stretch and twist like taffy as time passes, but its volume never changes. Information is perfectly conserved. The universe never forgets.", "orientation": "horizontal", "beats_json": make_beats(False), "target_duration_sec": 180})
videos.append({"video_id": "hz_v3_bra_ket_super", "concept_type": "QUANTUM", "header_title": "Vectors in Hilbert Space", "tagline": "Superposition as geometry", "question_text": "What does a ket vector |ψ⟩ represent?", "option_a": "A physical wave in the ether.", "option_b": "A state vector containing all probability amplitudes.", "option_c": "The exact position of a particle.", "option_d": "The energy of the vacuum.", "correct_answer": "B", "equations_json": json.dumps(["|\\psi\\rangle = \\alpha|0\\rangle + \\beta|1\\rangle", "P = |\\langle x|\\psi\\rangle|^2"]), "visual_data_json": make_visual("Bra-Ket Notation", "linear_algebra", "model", 5.0, -5.0, "rotating state vectors", False, transform="bloch_sphere", color="#FF006E"), "audio_script": "Paul Dirac invented a beautiful shorthand for quantum mechanics: the bra-ket notation. A ket, written like |ψ⟩, is just a vector. But not a vector in our 3D world. It’s a vector in Hilbert space, an abstract room where every direction represents a possible state of the universe. If you want to know the probability of finding the electron in a specific place, you just take the dot product of your state vector with the position vector, and square it. Superposition isn't a particle being in two places at once; it's just a vector pointing diagonally between two basis states. It’s pure geometry.", "orientation": "horizontal", "beats_json": make_beats(False), "target_duration_sec": 180})
videos.append({"video_id": "hz_v1_kinetic_gas", "concept_type": "THERMODYNAMICS", "header_title": "The Jiggling Atoms", "tagline": "Heat is just motion in disguise", "question_text": "What is temperature at the microscopic level?", "option_a": "A fluid called caloric.", "option_b": "The average kinetic energy of random molecular motion.", "option_c": "The total potential energy of bonds.", "option_d": "The color of the emitted light.", "correct_answer": "B", "equations_json": json.dumps(["PV = NkT", "\\frac{3}{2}kT = \\frac{1}{2}m\\langle v^2 \\rangle"]), "visual_data_json": make_visual("Kinetic Theory of Gases", "particle_gas", "model", 5.0, -5.0, "random walks and pressure", False, container_dims=[8.0, 4.0], num_particles=40, color="#8AC926"), "audio_script": "When you heat up a gas, you aren't adding some invisible fluid called 'caloric.' You are just making the atoms jiggle faster. Temperature is nothing more than the average kinetic energy of this random, chaotic motion. When these jiggling atoms hit the walls of a balloon, they bounce back, transferring momentum. Billions of these microscopic bounces per second average out to a smooth, macroscopic push. We call that pressure. The ideal gas law isn't a rule handed down from the heavens; it's just the statistical bookkeeping of a very large number of very tiny bouncing balls.", "orientation": "horizontal", "beats_json": make_beats(False), "target_duration_sec": 180})
videos.append({"video_id": "hz_v2_aharonov_bohm", "concept_type": "ELECTROMAGNETISM", "header_title": "Gauge Invariance", "tagline": "When potentials are real", "question_text": "Can a magnetic field affect an electron where the field is zero?", "option_a": "No, fields must touch particles.", "option_b": "Yes, via the Aharonov-Bohm phase shift.", "option_c": "Only if the electron is charged.", "option_d": "Only at absolute zero.", "correct_answer": "B", "equations_json": json.dumps(["\\Delta \\phi = \\frac{q}{\\hbar} \\oint \\vec{A} \\cdot d\\vec{l}", "\\nabla \\times \\vec{A} = 0 \\text{ locally}"]), "visual_data_json": make_visual("The Aharonov-Bohm Effect", "electromagnetic_wave", "model", 5.0, -5.0, "phase shifts in empty space", False, wave_type="interfering_paths", color="#FFBE0B"), "audio_script": "In classical physics, if the magnetic field is zero in a region, an electron flying through that region feels nothing. But quantum mechanics tells a different story. The electron wavefunction accumulates a phase shift determined not by the magnetic field, but by the vector potential A. If you split an electron beam around a shielded magnetic solenoid, the two paths will pick up different phases, even though they never touch a magnetic field. When they recombine, the interference pattern shifts. The vector potential isn't just a mathematical trick; it has a physical reality in the quantum phase.", "orientation": "horizontal", "beats_json": make_beats(False), "target_duration_sec": 180})
videos.append({"video_id": "hz_v3_spin_half", "concept_type": "QUANTUM", "header_title": "Spinors and 720 Degrees", "tagline": "The geometry of fermions", "question_text": "How many degrees must you rotate an electron to return it to its original state?", "option_a": "90 degrees", "option_b": "180 degrees", "option_c": "360 degrees", "option_d": "720 degrees", "correct_answer": "D", "equations_json": json.dumps(["|\\psi'\\rangle = e^{-i \\theta \\sigma_y / 2} |\\psi\\rangle", "\\sigma_x \\sigma_y = i \\sigma_z"]), "visual_data_json": make_visual("Spin 1/2", "angular_measurement", "model", 5.0, -5.0, "720-degree symmetry", False, rotation_type="spinor_dirac", color="#3A0CA3"), "audio_script": "In our everyday world, if you rotate an object 360 degrees, it comes back exactly to where it started. But an electron is a spin-1/2 particle, a spinor. If you rotate it 360 degrees, its wavefunction doesn't return to itself; it picks up a minus sign. It is physically inverted. You have to rotate it another 360 degrees—a full 720 degrees—to get back to the original state. This sounds like a mathematical quirk, but it is the reason the Pauli exclusion principle exists, which is the reason matter takes up space. If you and I were made of bosons, we would all collapse into the same state. You are solid because of 720-degree geometry.", "orientation": "horizontal", "beats_json": make_beats(False), "target_duration_sec": 180})
videos.append({"video_id": "hz_v1_entropy", "concept_type": "THERMODYNAMICS", "header_title": "Entropy & Microstates", "tagline": "Why time only moves forward", "question_text": "What does the Second Law of Thermodynamics actually forbid?", "option_a": "Energy creation.", "option_b": "A system moving from a probable macrostate to a highly improbable one.", "option_c": "Reversible friction.", "option_d": "Cooling a gas.", "correct_answer": "B", "equations_json": json.dumps(["S = k_B \\ln \\Omega", "\\Delta S_{univ} \\geq 0"]), "visual_data_json": make_visual("Entropy and Time", "concept_map", "model", 5.0, -5.0, "shuffling into chaos", False, map_type="microstate_lattice", color="#E63946"), "audio_script": "Why does a drop of ink spread out in water, but never spontaneously gather back into a drop? It’s not because of some mysterious 'force' of entropy. It’s just statistics. There are only a few ways for the ink molecules to be clumped together, but billions of ways for them to be mixed. As the molecules jostle and collide randomly, they simply wander into the states that have more combinations. The Second Law of Thermodynamics isn't a rigid law like gravity; it’s an overwhelming statistical certainty. Time’s arrow points in the direction of more probable configurations.", "orientation": "horizontal", "beats_json": make_beats(False), "target_duration_sec": 180})
videos.append({"video_id": "hz_v2_maxwell_speed", "concept_type": "ELECTROMAGNETISM", "header_title": "The Speed of Light", "tagline": "A consequence of the vacuum", "question_text": "What did Maxwell discover when he calculated the speed of electromagnetic waves?", "option_a": "It depends on the color.", "option_b": "It matched the known speed of light exactly.", "option_c": "It was infinite.", "option_d": "It varied with temperature.", "correct_answer": "B", "equations_json": json.dumps(["\\nabla \\times \\vec{E} = -\\frac{\\partial \\vec{B}}{\\partial t}", "c = \\frac{1}{\\sqrt{\\mu_0 \\epsilon_0}}"]), "visual_data_json": make_visual("Maxwell's Unification", "electromagnetic_wave", "model", 5.0, -5.0, "self-propagating fields", False, wave_type="transverse_E_B", color="#06D6A0"), "audio_script": "When Maxwell added his displacement current to Ampere's law, the equations suddenly allowed for waves. He calculated the speed of these waves using only constants from static electricity and magnetism experiments. The number he got was 3 times 10 to the 8 meters per second. He knew exactly what that number was. It was the speed of light. Light wasn't just analogous to electromagnetism; it *was* electromagnetism. A self-sustaining dance of electric and magnetic fields, leaping through the vacuum at the ultimate speed limit.", "orientation": "horizontal", "beats_json": make_beats(False), "target_duration_sec": 180})

