videos.append({"video_id": "vz_v1_gyro_precession", "concept_type": "MECHANICS", "header_title": "Why Tops Don't Fall", "tagline": "Angular momentum's stubbornness", "question_text": "Why does a spinning top precess instead of falling?", "option_a": "Air pressure holds it up.", "option_b": "The torque from gravity changes the direction of angular momentum.", "option_c": "Centrifugal force pushes it up.", "option_d": "The Earth's magnetic field.", "correct_answer": "B", "equations_json": json.dumps(["\\vec{\\tau} = \\frac{d\\vec{L}}{dt}"]), "visual_data_json": make_visual("Gyroscopic Precession", "rotational_motion", "model", 3.5, -3.5, "torque pulling the spin axis", True, object="top", color="#F72585"), "audio_script": "When a top spins, it has angular momentum pointing straight up its axis. Gravity tries to pull it down, creating a torque. But torque doesn't just pull things down; it changes the *direction* of angular momentum. Instead of falling over, the tip of the angular momentum vector gets dragged sideways. The top doesn't fall; it precesses. It's the exact same math that keeps the Earth's axis pointed at Polaris, and keeps a bicycle stable when you let go of the handlebars.", "orientation": "vertical", "beats_json": make_beats(True), "target_duration_sec": 60})
videos.append({"video_id": "vz_v3_quantum_tunnel", "concept_type": "QUANTUM", "header_title": "Quantum Tunneling", "tagline": "Leaking through walls", "question_text": "How does an alpha particle escape the nucleus?", "option_a": "It gains enough heat.", "option_b": "Its wavefunction exponentially decays, but doesn't reach zero inside the barrier.", "option_c": "It breaks the strong force.", "option_d": "It travels faster than light.", "correct_answer": "B", "equations_json": json.dumps(["\\psi(x) \\propto e^{-\\kappa x}", "\\kappa = \\frac{\\sqrt{2m(V-E)}}{\\hbar}"]), "visual_data_json": make_visual("Quantum Tunneling", "wave_pulse", "model", 3.5, -3.5, "exponential decay through the barrier", True, wave_type="evanescent", color="#4361EE"), "audio_script": "Classically, if a ball doesn't have enough energy to roll over a hill, it bounces back. But in quantum mechanics, particles are waves. When a matter wave hits a barrier it can't pass, it doesn't stop instantly. It decays exponentially inside the barrier. If the barrier is thin enough, the wave 'leaks' out the other side. There is a tiny, non-zero probability that the particle just appears on the other side. This is quantum tunneling, and it’s the exact reason the sun shines.", "orientation": "vertical", "beats_json": make_beats(True), "target_duration_sec": 60})
videos.append({"video_id": "vz_v2_lenz_law", "concept_type": "ELECTROMAGNETISM", "header_title": "Lenz's Law", "tagline": "The angry magnetic field", "question_text": "Why is there a minus sign in Faraday's Law?", "option_a": "Convention.", "option_b": "Conservation of Energy requires the induced current to oppose the change.", "option_c": "Magnetic monopoles exist.", "option_d": "Friction in the wire.", "correct_answer": "B", "equations_json": json.dumps(["\\mathcal{E} = -\\frac{d\\Phi_B}{dt}"]), "visual_data_json": make_visual("Lenz's Law", "vector_field", "model", 3.5, -3.5, "induced field fighting the change", True, field_type="dipole_opposing", color="#4CC9F0"), "audio_script": "Faraday discovered that changing magnetic fields create electric currents. But why the minus sign in the equation? Nature is stubborn. If pushing a magnet into a coil created a current that pulled the magnet in *faster*, you'd get infinite free energy. Instead, Lenz's Law says the induced current creates its own magnetic field that *fights* the change. It pushes back. The minus sign isn't just math; it is the universe enforcing the conservation of energy.", "orientation": "vertical", "beats_json": make_beats(True), "target_duration_sec": 60})
videos.append({"video_id": "vz_v1_phase_group", "concept_type": "MECHANICS", "header_title": "Phase vs Group Velocity", "tagline": "When waves walk", "question_text": "Can a wave's ripples move faster than the wave itself?", "option_a": "No, nothing beats c.", "option_b": "Yes, phase velocity can exceed c, but group velocity cannot.", "option_c": "Only in a vacuum.", "option_d": "Only for sound.", "correct_answer": "B", "equations_json": json.dumps(["v_p = \\frac{\\omega}{k}", "v_g = \\frac{d\\omega}{dk}"]), "visual_data_json": make_visual("Wave Packets", "beat_pattern", "model", 3.5, -3.5, "ripples moving through the envelope", True, wave_type="dispersive", color="#F72585"), "audio_script": "When you drop a stone in water, you see a group of ripples moving outward. But watch closely: the individual ripples appear at the back of the group, surge forward through the middle, and die at the front. The speed of the individual ripples is the 'phase velocity.' The speed of the whole group is the 'group velocity.' In quantum mechanics, the group velocity is the actual speed of the particle, and it can never exceed the speed of light, even if the phase ripples inside the wave packet are moving faster than c!", "orientation": "vertical", "beats_json": make_beats(True), "target_duration_sec": 60})
videos.append({"video_id": "vz_v3_heisenberg_fourier", "concept_type": "QUANTUM", "header_title": "Heisenberg is just Math", "tagline": "The Fourier transform trap", "question_text": "Why can't we know position and momentum exactly at the same time?", "option_a": "Our instruments are flawed.", "option_b": "A wave localized in space requires a wide spread of frequencies.", "option_c": "The observer changes the particle.", "option_d": "Photons bounce off electrons.", "correct_answer": "B", "equations_json": json.dumps(["\\Delta x \\Delta p \\geq \\frac{\\hbar}{2}"]), "visual_data_json": make_visual("Uncertainty Principle", "harmonic_decomposition", "model", 3.5, -3.5, "squeezing the pulse spreads the spectrum", True, wave_type="gaussian_pulse", color="#FF006E"), "audio_script": "People think the Heisenberg Uncertainty Principle is about clumsy observers bumping into electrons. It's not. It's pure geometry. A particle is a wave packet. If you want to know exactly where it is, you have to squeeze the wave into a tiny spike. But mathematically, the only way to build a sharp spike is to add together a huge variety of different wavelengths. And wavelength is momentum! You can't have a localized wave without a wide spread of momenta. Uncertainty isn't a measurement error; it's a property of waves.", "orientation": "vertical", "beats_json": make_beats(True), "target_duration_sec": 60})
videos.append({"video_id": "vz_v2_maxwell_div_b", "concept_type": "ELECTROMAGNETISM", "header_title": "No Magnetic Monopoles", "tagline": "Field lines must loop", "question_text": "Why do magnetic field lines always form closed loops?", "option_a": "Friction.", "option_b": "The divergence of the B-field is exactly zero.", "option_c": "Magnets are always dipoles.", "option_d": "The speed of light.", "correct_answer": "B", "equations_json": json.dumps(["\\nabla \\cdot \\vec{B} = 0", "\\oint \\vec{B} \\cdot d\\vec{A} = 0"]), "visual_data_json": make_visual("Divergence of B", "vector_field", "model", 3.5, -3.5, "lines entering equal lines leaving", True, field_type="dipole_closed", color="#4361EE"), "audio_script": "Electric field lines start on positive charges and end on negative charges. But magnetic field lines? They never start, and they never end. They must form closed loops. Why? Because as far as we know, there are no magnetic monopoles in the universe. If you cut a magnet in half, you don't get a north and a south; you get two smaller magnets. The mathematical way we say 'there are no magnetic sources' is that the divergence of the B-field is exactly zero.", "orientation": "vertical", "beats_json": make_beats(True), "target_duration_sec": 60})
videos.append({"video_id": "vz_v1_friction_atoms", "concept_type": "MECHANICS", "header_title": "The Reality of Friction", "tagline": "Mountains of atoms", "question_text": "What causes macroscopic kinetic friction?", "option_a": "Air resistance.", "option_b": "Cold welding and interlocking of microscopic surface asperities.", "option_c": "Electrostatic repulsion.", "option_d": "Viscosity of the vacuum.", "correct_answer": "B", "equations_json": json.dumps(["F_f = \\mu_k N"]), "visual_data_json": make_visual("Atomic Friction", "shape", "model", 3.5, -3.5, "interlocking asperities tearing", True, shape_type="rough_surface_slide", color="#FB5607"), "audio_script": "We write F equals mu N for friction, as if it's a fundamental law of nature. But it's not. It's a messy macro-statistic. Zoom in on two 'smooth' pieces of metal sliding past each other, and you see jagged mountains of atoms crashing into each other. They cold-weld, they break, they vibrate. All that chaotic microscopic breaking and vibrating turns organized kinetic energy into disorganized heat. Friction isn't a force; it's the sound of atoms tearing each other apart.", "orientation": "vertical", "beats_json": make_beats(True), "target_duration_sec": 60})
videos.append({"video_id": "vz_v3_pauli_exclusion", "concept_type": "QUANTUM", "header_title": "The Pauli Exclusion", "tagline": "Why matter takes up space", "question_text": "Why can't two electrons occupy the exact same state?", "option_a": "They repel electrically.", "option_b": "Their combined wavefunction must be antisymmetric.", "option_c": "They have different masses.", "option_d": "Gravity prevents it.", "correct_answer": "B", "equations_json": json.dumps(["\\psi(1,2) = -\\psi(2,1)", "\\psi(1,1) = 0"]), "visual_data_json": make_visual("Fermion Antisymmetry", "linear_algebra", "model", 3.5, -3.5, "swapping coordinates flips the sign", True, transform="matrix_swap", color="#7209B7"), "audio_script": "Why doesn't all the matter in the universe just collapse into the lowest energy state? The Pauli Exclusion Principle. It says two fermions cannot share the same quantum state. Mathematically, if you swap the labels of two electrons, the wavefunction must flip its sign. If they were in the exact same state, swapping them wouldn't change anything, but the math demands it flips sign. The only number that equals its own negative is zero. Therefore, the probability of them being in the same state is exactly zero.", "orientation": "vertical", "beats_json": make_beats(True), "target_duration_sec": 60})
