try:
    print(f"[*] Attempting to write to: {OUTPUT_FILE}")
    
    # Open with 'utf-8-sig' to ensure Excel and parsers don't break math symbols
    with open(OUTPUT_FILE, "w", newline="", encoding="utf-8-sig") as f:
        
        # csv.QUOTE_ALL forces EVERY cell to be wrapped in quotes.
        # This prevents commas inside the JSON arrays from breaking the CSV columns!
        writer = csv.DictWriter(f, fieldnames=FIELDNAMES, quoting=csv.QUOTE_ALL)
        writer.writeheader()
        
        for v in videos:
            row = {k: v.get(k, "") for k in FIELDNAMES}
            writer.writerow(row)
            
    print("[✓] SUCCESS: CSV written perfectly.")
    
    # Verification step: Read back the first row to prove it worked
    with open(OUTPUT_FILE, "r", encoding="utf-8-sig") as f:
        reader = csv.DictReader(f)
        first_row = next(reader)
        print(f"[✓] Verified first row ID: {first_row['video_id']}")
        print(f"[*] Next steps:")
        print(f"    1. python3 schema_validator.py {OUTPUT_FILE}")
        print(f"    2. python3 batch_runner.py --csv {OUTPUT_FILE}")
        
except Exception as e:
    print(f"[!] ERROR: Failed to write CSV. Details: {e}")
    sys.exit(1)
